import{_ as o,l,o as e,c as n,v as r,p as s,x as t,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"反应离子刻蚀转印","description":"","frontmatter":{"title":"反应离子刻蚀转印","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/rie-pattern-transfer.md","filePath":"litho/rie-pattern-transfer.md","lastUpdated":1789023840000}'),d={name:"litho/rie-pattern-transfer.md"};function A(c,a,B,u,_,f){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="反应离子刻蚀转印" tabindex="-1">反应离子刻蚀转印 <a class="header-anchor" href="#反应离子刻蚀转印" aria-label="Permalink to &quot;反应离子刻蚀转印&quot;">​</a></h1><div class="epigraph"><p>显影只留下一层有机浮雕。器件要的是硬掩模或硅上的永久边；把胶图形变成那条边的，是离子与中性自由基的协同，而不是再一次投影成像。</p><footer>—— 对照 Coburn–Winters 对等离子体表面协同的论述，以及刻蚀教材把 RIE 写成各向异性转印</footer></div><p><a href="/litho/compact-vs-rigorous">上一课</a>把刻蚀收成 OPC 里的紧凑偏置：密度一变，CD 平移一截。缺口是这条偏置在腔体里从哪来。本课钉反应离子刻蚀（RIE）：胶图形如何转到硬掩模和硅。<a href="/litho/litho-process-flow">光刻流程</a>已经排过「显影之后才转印」；这里不重讲涂胶顺序，只补转移函数的物理。深宽比与负荷如何让速率随开口变，留给<a href="/litho/etch-loading-ar">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先进节点胶薄，选择比不够直接啃硅或厚介质。产线先把胶转到 SOC / SiARC、氮化物或金属硬掩模，再往下刻。若把显影后 SEM 当成栅极 CD，是把转印偏置算进了镜头。上一课的紧凑核假定存在一个稳定的「胶 → 衬底」映射；映射一漂，全芯片 OPC 跟着漂。</p><p>缺口因此是：各向异性从哪来、选择比怎么买、以及为何离子能量与化学不能只拧一个。纯溅射损伤大、侧壁差；纯化学各向同性，细线立不住。RIE 要的是两者协同。</p><h3 id="胶不是理想二元掩模" tabindex="-1">胶不是理想二元掩模 <a class="header-anchor" href="#胶不是理想二元掩模" aria-label="Permalink to &quot;胶不是理想二元掩模&quot;">​</a></h3><p>胶边有斜角、LWR 和残胶。等离子体先看到的是这层形貌，不是版图。选择比不够时，胶顶被削，开口变宽，CD 随刻蚀时间走。硬掩模的作用是把「成像预算」和「深度预算」拆开：薄胶只负责定义边，纵向深度交给更耐打的膜。这与 <a href="/litho/ald-ale">ALD/ALE</a> 的循环修整是同一纵向危机的两种回答，本课先停在连续 RIE。</p><p><span class="marginnote">ADI 与 AEI 必须分开报。把刻蚀后 CD 写进扫描仪分辨率规格，是类别错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RIE 在低气压等离子体里同时提供：垂直入射的离子，以及能与表面反应的中性自由基。Coburn 与 Winters 的经典图像是协同——离子轰击或电子协助让本不会快速挥发的反应进行；关掉离子，化学速率掉下去；只开离子，物理溅射也慢。各向异性来自离子的方向性，侧壁靠钝化膜挡住横向吃。</p><p>工艺旋钮是源功率、偏置功率、气压、气体比和温度。偏置抬离子能量，剖面变直，损伤与选择比恶化。聚合物气体（如含氟碳）在侧壁沉积，窗口是「够钝化而不封口」。硬掩模打开后，硅或介质用另一套化学，胶可能已经所剩无几。教材把这条链写成：显影浮雕 → 开硬掩模 → 主刻 → 过刻 → 去胶；每段有自己的终点探测。</p>',12)),(e(),s(h,null,{default:t(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E6%98%BE%E5%BD%B1%E8%83%B6%E6%B5%AE%E9%9B%95%22%5D%20--%3E%20HM%5B%22%E5%BC%80%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20HM%20--%3E%20SI%5B%22%E4%B8%BB%E5%88%BB%E7%A1%85%20%2F%20%E4%BB%8B%E8%B4%A8%22%5D%0A%20%20SI%20--%3E%20OX%5B%22%E8%BF%87%E5%88%BB%E4%B8%8E%E5%8E%BB%E8%83%B6%22%5D%0A%20%20ION%5B%22%E5%AE%9A%E5%90%91%E7%A6%BB%E5%AD%90%22%5D%20--%3E%20RIE%5B%22RIE%20%E5%8D%8F%E5%90%8C%22%5D%0A%20%20RAD%5B%22%E4%B8%AD%E6%80%A7%E8%87%AA%E7%94%B1%E5%9F%BA%22%5D%20--%3E%20RIE%0A%20%20RIE%20--%3E%20HM%0A%20%20RIE%20--%3E%20SI%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="终点与过刻不是光学焦深" tabindex="-1">终点与过刻不是光学焦深 <a class="header-anchor" href="#终点与过刻不是光学焦深" aria-label="Permalink to &quot;终点与过刻不是光学焦深&quot;">​</a></h3><p>光学窗在剂量–焦点平面；刻蚀窗在终点信号与过刻百分比。开完硬掩模必须过刻，否则局部残膜变短路或开路。过刻吃的是选择比：够，CD 几乎停；不够，CD 随过刻线性漂，上一课的紧凑偏置就不是常数。本课不写某台国产刻蚀机的片/小时，只要求把 AEI 目标从曝光机规格里拆出去。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Coburn–Winters 协同把「化学反应」和「离子辅助脱附」乘在一起：表面先被自由基改性，离子再把改性层打掉或激活。侧壁离子通量小，钝化得以留下，剖面各向异性。这与溅射刻蚀的物理打磨不同，也与湿法的各向同性不同。转移函数可以放大或缩小 CD，也可以把 LWR 的高频滤掉、把低频留下，所以「光刻分辨率」若停在显影后，最终栅极边仍可能被这一段改写。</p><p>多重图形里，第一次 RIE 的结果是第二次涂胶的形貌，反射与涂覆均匀性都变。<a href="/litho/lele-multipattern">LELE</a> 不是两次快门，是两次曝光–刻蚀串联。SADP 的 spacer 厚度在这一段定义，不在空中像里定义。</p><p><span class="marginnote">选择比是对特定膜对、特定偏置的窗口，不是材料表上的一个永久数字。换硬掩模或换胶，协同点要重标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是等离子体源设计课，不写 ICP 线圈匝数。也不把 ALE 的「每循环一埃」提前写成 RIE 的升级开关——循环刻蚀在薄膜课。RIE 不修复套刻，不抬 \\(k_1\\)；它只把已有浮雕变成衬底图形。损伤、电荷与聚合物残留会进电学变差，看起来像光刻热点，根因在过刻和偏置。</p><p>不要用某一代逻辑的良率证明「有 RIE 所以一定差」。转印链的责任隔离是：光学出空中像，胶出浮雕，RIE 出永久边。下一课才问：同样的食谱，为什么密区和疏区、浅槽和深孔速率不同。</p><p><span class="marginnote">出处：J. W. Coburn, H. F. Winters 对离子辅助气体表面化学与等离子体刻蚀机制的公开论述；刻蚀教材中的 RIE 各向异性与选择比。不编造未公开的硅刻蚀速率表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RIE 用离子与自由基协同，把胶浮雕转到硬掩模和硅，是光刻链的最后一次「成像」。</li><li>薄胶先转硬掩模；ADI 与 AEI 的 CD 不是同一个量。</li><li>Coburn–Winters 协同解释各向异性与选择比窗口，不是纯溅射也不是纯湿法。</li><li>OPC 里的刻蚀偏置是这一段的紧凑影子，腔体一漂核就谎。</li><li>深宽比与负荷下一课。</li><li>出处：Coburn–Winters；刻蚀教材中的图形转印。</li></ul>',12))])}const C=o(d,[["render",A]]);export{m as __pageData,C as default};
